CREATE TABLE IF NOT EXISTS players (uuid TEXT PRIMARY KEY, name TEXT NOT NULL, points INTEGER NOT NULL DEFAULT 0, streak INTEGER NOT NULL DEFAULT 0,
  last_day INTEGER NOT NULL DEFAULT 0, last_beat INTEGER NOT NULL DEFAULT 0, active_minutes INTEGER NOT NULL DEFAULT 0, imported INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL,
  week_id INTEGER NOT NULL DEFAULT 0, week_minutes INTEGER NOT NULL DEFAULT 0, week_paid INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS owned (uuid TEXT NOT NULL, item TEXT NOT NULL, PRIMARY KEY (uuid, item));
CREATE TABLE IF NOT EXISTS outfits (uuid TEXT PRIMARY KEY, outfit TEXT NOT NULL, show INTEGER NOT NULL DEFAULT 1, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, uuid TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_uuid ON sessions (uuid);
CREATE TABLE IF NOT EXISTS nonces (server_id TEXT PRIMARY KEY, uuid TEXT NOT NULL, name TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS history (uuid TEXT NOT NULL, ts INTEGER NOT NULL, delta INTEGER NOT NULL, reason TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS history_uuid ON history (uuid, ts);
